const cache = new Map<string, CityInteriorEntry>();

/** Interior entry for a sprite id, or null when the catalogue has none. */
export function cityInterior(id: string): CityInteriorEntry | null {
  const hit = cache.get(id);
  if (hit) return hit;
  const raw = RAW[id];
  if (!raw) return null;
  const zones = raw[3].map((z) => {
    const interactive = !z.startsWith('!');
    const [zid, name] = (interactive ? z : z.slice(1)).split('|') as [string, string];
    return { id: zid, name, interactive };
  });
  const entry: CityInteriorEntry = { name: raw[0], archetype: raw[1], technical: raw[2] === 1, zones };
  cache.set(id, entry);
  return entry;
}

export const CITY_INTERIOR_IDS = Object.keys(RAW);
